@startuml

class Organizer {
  + firstName : string
  + lastName : string
  + email : string
  + postalAddress : string
  + phoneNumber : string
  + password : string
}

class EventType {
  + name : string
}

class Location {
  + name : string
  + address : string
}

class Event {
  + occasion : string
  + startDateTime : datetime
  + endDateTime : datetime
}

class Attendee {
  + firstName : string
  + lastName : string
  + email : string
  + password : string
  + attendanceStatus : string
}

class Task {
  + description : string
  + status : string
}

class TaskAssignment {
  + isCompleted : boolean
}

class EventTask {
  + isDone : string
}

class EventAttendee {
  + status : string
}

Organizer "1..*" -- "1" Event : organizes
Organizer "0..1" -- "0..*" Event : attends
Organizer "1" -- "*" EventType : selects/creates
Organizer "1" -- "*" Location : selects/creates
Organizer "1" -- "*" Task : creates

Event "1" -- "*" EventType : is of type
Event "1" -- "1" Location : at
Event "1" *-- "*" EventTask : has checklist
Event "1" -- "*" Attendee : invites

Attendee "0..1" -- "0..*" EventAttendee : responds to
Event "1" -- "*" EventAttendee : has

EventTask "0..1" -- "0..1" Attendee : assigned to
EventTask "1" -- "0..1" TaskAssignment : tracks

Attendee "1" -- "*" TaskAssignment : brings

@enduml

